"""Serve stored images from this origin, so browsers never contact the object store."""

import re

from fastapi import APIRouter
from fastapi.responses import StreamingResponse

from app.errors import NotFoundError
from app.services.images import STORED_CONTENT_TYPE
from app.storage.client import Storage

router = APIRouter(tags=["media"])

# Keys are generated by the server; anything else is not ours to look up.
STORAGE_KEY = re.compile(r"^[a-f0-9]{32}(-thumb)?\.webp$")


@router.get("/img/{key}", response_model=None)
def read_image(key: str, storage: Storage) -> StreamingResponse:
    """Stream one stored image."""
    if not STORAGE_KEY.fullmatch(key):
        raise NotFoundError
    chunks, size = storage.stream(key)
    return StreamingResponse(
        chunks,
        media_type=STORED_CONTENT_TYPE,
        headers={"Content-Length": str(size), "Cache-Control": "public, max-age=31536000, immutable"},
    )
